∀ {R : Type} [inst : Grind.CommRing R] (a b : R),
  have N := a + b + -(-1 + 0) * a * b;
  1 - -1 * N = (1 - -1 * a) * (1 - -1 * b)

∀ {R : Type} [inst : Grind.CommRing R] (c a b : R),
  have N := a + b + 2 * c * a * b;
  have D := 1 - c * c * a * b;
  N * ((1 + c * a) * (1 + c * b)) = (D + c * N) * (a * (1 + c * b) + b * (1 + c * a))

∀ {R : Type} [inst : Grind.CommRing R] (i a b : R),
  i * i = -1 →
    have N := a + b;
    have D := 1 - a * b;
    (D + i * N) * ((1 - i * a) * (1 - i * b)) = (1 + i * a) * (1 + i * b) * (D - i * N)

∀ {R : Type} [inst : Grind.CommRing R] (r1 r2 a b : R),
  have N := a + b + -(r1 + r2) * a * b;
  have D := 1 - r1 * r2 * a * b;
  (D - r1 * N) * ((1 - r2 * a) * (1 - r2 * b)) = (1 - r1 * a) * (1 - r1 * b) * (D - r2 * N)

